<div class="page-heading"><div><div class="eyebrow">Administrasi</div><h1>Log aktivitas</h1><p>Order yang seluruh UTTP-nya selesai dan catatan tindakan sistem.</p></div></div>
<form class="card filter-card" method="get" action="<?= site_url('petugas/aktivitas') ?>"><div class="form-grid">
<label>Jenis catatan<select name="scope"><option value="completed"<?= $filters['scope']==='completed'?' selected':'' ?>>Order selesai</option><option value="system"<?= $filters['scope']==='system'?' selected':'' ?>>Aktivitas sistem</option></select></label>
<label>Dari tanggal<input type="date" name="date_from" value="<?= e($filters['date_from']) ?>"></label><label>Sampai tanggal<input type="date" name="date_to" value="<?= e($filters['date_to']) ?>"></label>
<label>Jenis UTTP<select name="uttp_type_id"><option value="">Semua jenis</option><?php foreach ($types as $type): ?><option value="<?= (int)$type->id ?>"<?= $filters['uttp_type_id']==$type->id?' selected':'' ?>><?= e($type->type_name) ?></option><?php endforeach; ?></select></label></div>
<button class="button primary small-button" type="submit">Terapkan filter</button> <a class="button outline small-button" href="<?= site_url('petugas/aktivitas') ?>">Bulan ini</a></form>
<section class="card table-card"><div class="filter-results"><span><strong><?= (int)$pagination['total'] ?></strong> <?= $filters['scope']==='system'?'aktivitas':'order selesai' ?> ditemukan</span></div>
<?php if ($rows): ?><div class="table-scroll"><table class="data-table"><thead><?php if ($filters['scope']==='system'): ?><tr><th>Waktu</th><th>Pelaku</th><th>Tindakan</th><th>Objek</th><th>Keterangan</th></tr><?php else: ?><tr><th>No. order</th><th>Pemohon</th><th>Layanan</th><th>UTTP</th><th>Status</th><th>Diajukan</th><th>Selesai</th><th>Penera</th></tr><?php endif; ?></thead><tbody>
<?php foreach ($rows as $row): if ($filters['scope']==='system'): ?><tr><td data-label="Waktu"><?= e(tanggal_id($row->created_at,TRUE)) ?></td><td data-label="Pelaku"><?= e($row->actor_name ?: 'Sistem') ?></td><td data-label="Tindakan"><strong><?= e(ucwords(str_replace('_',' ',$row->action_code))) ?></strong></td><td data-label="Objek"><?= e($row->entity_type) ?><?= $row->entity_id ? ' #'.(int)$row->entity_id : '' ?></td><td data-label="Keterangan"><?= e($row->summary ?: '—') ?></td></tr>
<?php else: ?><tr class="clickable-row" data-row-url="<?= site_url('petugas/permohonan/'.$row->request_id.'?tab=process') ?>" tabindex="0" role="link"><td data-label="No. order"><a class="table-link" href="<?= site_url('petugas/permohonan/'.$row->request_id.'?tab=process') ?>"><?= e($row->request_no) ?></a></td><td data-label="Pemohon"><?= e($row->organization_name ?: $row->applicant_name) ?></td><td data-label="Layanan"><?= e(master_label('service_type',$row->service_type)) ?></td><td data-label="UTTP"><?= (int)$row->unit_count ?></td><td data-label="Status"><span class="badge success">Selesai</span></td><td data-label="Diajukan"><?= e(tanggal_id($row->submitted_at,TRUE)) ?></td><td data-label="Selesai"><?= e(tanggal_id($row->completed_at,TRUE)) ?></td><td data-label="Penera"><?= e($row->penera_name ?: '—') ?></td></tr><?php endif; endforeach; ?></tbody></table></div>
<?php else: ?><div class="table-empty"><strong><?= $filters['scope']==='completed'?'Belum ada order selesai pada rentang ini':'Belum ada tindakan sistem pada rentang ini' ?></strong><?= $filters['scope']==='completed'?'Order tampil setelah seluruh UTTP mencapai status akhir. Pilih Aktivitas sistem untuk melihat tindakan yang sudah terjadi.':'Ubah tanggal untuk melihat tindakan lain.' ?></div><?php endif; ?>
<?= metro_pager($pagination,'petugas/aktivitas',array_filter(array('scope'=>$filters['scope'],'date_from'=>$filters['date_from'],'date_to'=>$filters['date_to'],'uttp_type_id'=>$filters['uttp_type_id']),'strlen')) ?></section>
